export function getBlogBySlug(slug) {
  if (!slug) return null;
  return BLOGS.find(b => b.slug.toLowerCase() === slug.toLowerCase()) || null;
}

export function getRelatedBlogs(currentBlog, count = 3) {
  if (!currentBlog) return [];
  const otherBlogs = BLOGS.filter(b => b.id !== currentBlog.id);

  // Score relevance
  const scored = otherBlogs.map(b => {
    let score = 0;
    if (b.category === currentBlog.category) score += 10;
    if (b.tags && currentBlog.tags) {
      const sharedTags = b.tags.filter(t => currentBlog.tags.includes(t));
      score += sharedTags.length * 3;
    }
    return { blog: b, score };
  });

  scored.sort((a, b) => b.score - a.score);
  return scored.slice(0, count).map(s => s.blog);
}

export function getAdjacentBlogs(currentBlog) {
  if (!currentBlog) return { prev: null, next: null };
  const idx = BLOGS.findIndex(b => b.id === currentBlog.id);
  if (idx === -1) return { prev: null, next: null };
  const prev = idx > 0 ? BLOGS[idx - 1] : null;
  const next = idx < BLOGS.length - 1 ? BLOGS[idx + 1] : null;
  return { prev, next };
}
